from __future__ import annotations

from typing import Any

_GAP_BREAK_S_SINGING = 0.65


_MAX_CUE_S_SINGING = 9.0


_MAX_JOIN_CHARS_SINGING = 22


_SINGING_WORD_PUNCT_END = frozenset("，,、。！？!?．.｡…；;：:")


def _singing_word_chars(word: dict[str, Any] | str) -> int:
    if isinstance(word, dict):
        text = str(word.get("word") or "")
    else:
        text = str(word or "")
    # Punctuation does not count toward karaoke density.
    return sum(1 for ch in text if not ch.isspace() and ch not in _SINGING_WORD_PUNCT_END)


def _singing_seg_dur(ws: list[dict[str, Any]]) -> float:
    if not ws:
        return 0.0
    return max(0.0, float(ws[-1].get("end") or 0) - float(ws[0].get("start") or 0))


def _singing_seg_chars(ws: list[dict[str, Any]]) -> int:
    return sum(_singing_word_chars(w) for w in ws)


def _singing_gaps(ws: list[dict[str, Any]]) -> list[float]:
    out: list[float] = []
    for i in range(1, len(ws)):
        out.append(max(0.0, float(ws[i].get("start") or 0) - float(ws[i - 1].get("end") or 0)))
    return out


def _singing_ends_phrase(word: dict[str, Any]) -> bool:
    text = str(word.get("word") or "").strip()
    return bool(text) and text[-1] in _SINGING_WORD_PUNCT_END


def _singing_strip_cue_text(text: str) -> str:
    t = str(text or "").strip()
    while t and t[-1] in _SINGING_WORD_PUNCT_END:
        t = t[:-1].rstrip()
    return t


def _singing_apply_transcript_punct(
    words: list[dict[str, Any]],
    transcript: str,
) -> list[dict[str, Any]]:
    """Project ASR phrase punctuation onto ForcedAligner tokens (char walk).

    Aligners often drop ，。 while Qwen ASR keeps them — those marks are the
    most reusable lyric-line boundaries across songs/tempos.
    """
    if not words or not transcript:
        return words
    # Flatten aligner chars → owning word index (skip punct already on tokens).
    owners: list[int] = []
    for wi, w in enumerate(words):
        for ch in str(w.get("word") or ""):
            if ch.isspace() or ch in _SINGING_WORD_PUNCT_END:
                continue
            owners.append(wi)
    if not owners:
        return words
    marked: set[int] = set()
    oi = 0
    for ch in str(transcript):
        if ch.isspace():
            continue
        if ch in _SINGING_WORD_PUNCT_END:
            if oi > 0:
                marked.add(owners[min(oi, len(owners)) - 1])
            continue
        oi += 1
        if oi >= len(owners):
            break
    if not marked:
        return words
    out: list[dict[str, Any]] = []
    for wi, w in enumerate(words):
        item = dict(w)
        if wi in marked and not _singing_ends_phrase(item):
            item["word"] = str(item.get("word") or "") + "，"
        out.append(item)
    return out


def _singing_split_on_punct(
    ws: list[dict[str, Any]],
    *,
    min_chars: int = 4,
) -> list[list[dict[str, Any]]]:
    """Hard cuts where tokens carry phrase punctuation (aligner or ASR-projected)."""
    if not ws:
        return []
    parts: list[list[dict[str, Any]]] = []
    buf: list[dict[str, Any]] = []
    for w in ws:
        buf.append(w)
        if _singing_ends_phrase(w) and _singing_seg_chars(buf) >= min_chars:
            parts.append(buf)
            buf = []
    if buf:
        parts.append(buf)
    return parts


def _singing_gap_threshold(ws: list[dict[str, Any]]) -> float:
    """Conservative outlier threshold: only clear breaths vs local melisma."""
    gaps = [g for g in _singing_gaps(ws) if g > 1e-3]
    if not gaps:
        return 0.70
    gaps_u = sorted(gaps)
    med = gaps_u[len(gaps_u) // 2]
    return max(0.42, min(1.10, med * 3.8))


def _singing_split_at_gaps(
    ws: list[dict[str, Any]],
    thr: float,
    *,
    min_chars: int = 4,
) -> list[list[dict[str, Any]]]:
    """Split only on clear pauses with a real lyric chunk on *both* sides."""
    if not ws:
        return []
    parts: list[list[dict[str, Any]]] = []
    buf: list[dict[str, Any]] = [ws[0]]
    for i in range(1, len(ws)):
        gap = max(0.0, float(ws[i].get("start") or 0) - float(ws[i - 1].get("end") or 0))
        right_chars = _singing_seg_chars(ws[i:])
        if (
            gap >= thr
            and _singing_seg_chars(buf) >= min_chars
            and right_chars >= min_chars
        ):
            parts.append(buf)
            buf = [ws[i]]
        else:
            buf.append(ws[i])
    if buf:
        parts.append(buf)
    return parts


def _singing_best_cut_index(
    ws: list[dict[str, Any]],
    *,
    force: bool,
    soft_dur_s: float,
) -> int:
    """Index i means cut *after* ws[i]. -1 = no acceptable cut."""
    if len(ws) < 4:
        return -1
    gaps = _singing_gaps(ws)
    if not gaps:
        return -1
    gaps_pos = [g for g in gaps if g > 1e-3]
    med = sorted(gaps_pos)[len(gaps_pos) // 2] if gaps_pos else 0.0
    soft_floor = max(0.10, med * 1.25) if med > 1e-3 else 0.16
    best_i = -1
    best_score = -1.0
    dur = max(0.05, _singing_seg_dur(ws))
    target = max(1.8, float(soft_dur_s) * 0.82)
    for i, gap in enumerate(gaps):
        left, right = ws[: i + 1], ws[i + 1 :]
        lc, rc = _singing_seg_chars(left), _singing_seg_chars(right)
        # Soft cuts need a real chunk on both sides (avoid 自信可|改变未来 peels).
        min_side = 2 if force else 4
        if lc < min_side or rc < min_side:
            continue
        if not force and float(gap) < soft_floor:
            continue
        left_dur = _singing_seg_dur(left)
        # Prefer karaoke-sized left half over peeling at a slightly larger melisma gap.
        prox = 1.0 - min(1.0, abs(left_dur - target) / max(0.6, target))
        bal = 1.0 - abs(left_dur - _singing_seg_dur(right)) / dur
        score = float(gap) * (0.55 + 0.20 * max(0.0, bal) + 0.25 * max(0.0, prox))
        if lc >= 4 and rc >= 4:
            score += 0.01
        if score > best_score:
            best_score = score
            best_i = i
    if best_i < 0:
        return -1
    if gaps[best_i] < 0.08 and not force:
        return -1
    return best_i


def _singing_pack_duration(
    ws: list[dict[str, Any]],
    *,
    soft_dur_s: float,
    hard_dur_s: float,
    max_chars: int,
) -> list[list[dict[str, Any]]]:
    """Grow a cue until soft duration, then cut at the best *local* gap.

    Song-agnostic: tempo changes char density, but karaoke lines still cluster
    around a few seconds. Char count is only a readability ceiling — never a
    fixed soft target like \"9 chars\".
    """
    if not ws:
        return []
    soft_chars = max(12, int(max_chars))
    out: list[list[dict[str, Any]]] = []
    i = 0
    n = len(ws)
    while i < n:
        j = i
        while j < n - 1:
            nxt = ws[i : j + 2]
            nd = _singing_seg_dur(nxt)
            nc = _singing_seg_chars(nxt)
            over_soft = nd > soft_dur_s or nc > soft_chars
            over_hard = nd > hard_dur_s or nc > max_chars
            if not over_soft and not over_hard:
                j += 1
                continue
            buf = ws[i : j + 1]
            cut = _singing_best_cut_index(
                buf, force=over_hard, soft_dur_s=soft_dur_s
            )
            if cut >= 0 and _singing_seg_chars(buf[: cut + 1]) >= 2:
                out.append(buf[: cut + 1])
                i = i + cut + 1
                break
            if over_hard:
                mid = max(1, min(len(buf) - 2, len(buf) // 2))
                out.append(buf[: mid + 1])
                i = i + mid + 1
                break
            # Soft budget only + no pause outlier → keep growing (melisma-safe).
            j += 1
        else:
            out.append(ws[i:])
            break
    return out


def _singing_merge_tiny(
    parts: list[list[dict[str, Any]]],
    *,
    max_chars: int,
    hard_dur_s: float,
    soft_dur_s: float,
) -> list[list[dict[str, Any]]]:
    if not parts:
        return []
    out: list[list[dict[str, Any]]] = [list(parts[0])]
    for part in parts[1:]:
        prev = out[-1]
        gap = max(0.0, float(part[0].get("start") or 0) - float(prev[-1].get("end") or 0))
        merged_chars = _singing_seg_chars(prev) + _singing_seg_chars(part)
        merged_dur = max(
            0.0,
            float(part[-1].get("end") or 0) - float(prev[0].get("start") or 0),
        )
        lc, rc = _singing_seg_chars(prev), _singing_seg_chars(part)
        ld, rd = _singing_seg_dur(prev), _singing_seg_dur(part)
        # Glue orphans / flash tails; do not re-glue two full lyric lines.
        orphan = lc <= 2 or rc <= 2 or ld < 1.05 or rd < 1.05
        short_chunk = (lc <= 4 and ld < 2.15) or (rc <= 4 and rd < 2.15)
        if (
            (orphan or short_chunk)
            and gap <= 1.05
            and merged_chars <= max_chars
            and merged_dur <= max(hard_dur_s, soft_dur_s * 1.25)
        ):
            out[-1] = prev + part
        else:
            out.append(list(part))
    return out


def _words_to_singing_cues(
    words: list[dict[str, Any]],
    *,
    transcript: str = "",
    max_chars: int = 18,
    soft_dur_s: float = 5.0,
    hard_dur_s: float = 7.5,
    max_cue_s: float = _MAX_CUE_S_SINGING,
) -> list[dict[str, Any]]:
    """Pack ForcedAligner words into karaoke lines (song-agnostic).

    Reusable signals (not a fixed CJK char target like 9/10):
    1) ASR/aligner phrase punctuation (hard boundaries)
    2) clear relative pause outliers vs local melisma
    3) **duration-budget** packing (~XLSub line length in seconds)
    4) overflow cuts prefer local gaps whose left half ≈ soft target
    5) merge flash leftovers; char count only as readability ceiling
    """
    if not words:
        return []
    char_cap = max(12, int(max_chars))
    soft_dur = max(2.0, float(soft_dur_s))
    hard_dur = max(soft_dur + 0.5, float(hard_dur_s))
    cue_cap = max(2.0, float(max_cue_s))
    packed_words = _singing_apply_transcript_punct(words, transcript)
    parts = _singing_split_on_punct(packed_words, min_chars=4)
    refined: list[list[dict[str, Any]]] = []
    for part in parts:
        thr = _singing_gap_threshold(part)
        for chunk in _singing_split_at_gaps(part, thr, min_chars=4):
            refined.extend(
                _singing_pack_duration(
                    chunk,
                    soft_dur_s=soft_dur,
                    hard_dur_s=hard_dur,
                    max_chars=char_cap,
                )
            )
    refined = _singing_merge_tiny(
        refined,
        max_chars=char_cap,
        hard_dur_s=hard_dur,
        soft_dur_s=soft_dur,
    )
    out: list[dict[str, Any]] = []
    for buf in refined:
        text = _singing_strip_cue_text("".join(str(w.get("word") or "") for w in buf))
        if not text:
            continue
        start = float(buf[0].get("start") or 0)
        end = float(buf[-1].get("end") or start)
        out.append(
            {
                "start": start,
                "end": min(max(end, start + 0.25), start + cue_cap),
                "text": text,
                "words": list(buf),
            }
        )
    return out
